#include <stdio.h>

int heap[128];
int hn = 0;

void push(int x) {
    heap[hn] = x;
    int i = hn++;
    while (i > 0 && heap[(i - 1) / 2] > heap[i]) {
        int t = heap[i];
        heap[i] = heap[(i - 1) / 2];
        heap[(i - 1) / 2] = t;
        i = (i - 1) / 2;
    }
}

void pop(void) {
    heap[0] = heap[--hn];
    int i = 0;
    while (1) {
        int l = 2 * i + 1, r = 2 * i + 2, s = i;
        if (l < hn && heap[l] < heap[s]) s = l;
        if (r < hn && heap[r] < heap[s]) s = r;
        if (s == i) break;
        int t = heap[i];
        heap[i] = heap[s];
        heap[s] = t;
        i = s;
    }
}

void kLargest(int a[], int n, int k) {
    for (int i = 0; i < n; i++) {
        push(a[i]);
        if (hn > k) pop();
    }
    int result[16];
    for (int i = k - 1; i >= 0; i--) {
        result[i] = heap[0];
        pop();
    }
    for (int i = 0; i < k; i++) printf("%d ", result[i]);
}

